(7669748, 1251585, 173844, '<td valign="top">Congratulations on winning the blue.  This is too appealing not to.  By the way, this is one of the images I wish I was capable of taking.</td>', 'Congratulations on winning the blue.  This is too appealing not to.  By the way, this is one of the images I wish I was capable of taking.', '2020-07-13 17:34:01.000000', NULL, 0),
(7669749, 1251662, 173844, '<td valign="top">Congratulations on winning the red.  I''m really pleased that a few people thought this was mine, and I''ll accept the compliment.</td>', 'Congratulations on winning the red.  I''m really pleased that a few people thought this was mine, and I''ll accept the compliment.', '2020-07-13 17:36:06.000000', NULL, 0),
(7669750, 1251254, 173844, '<td valign="top">Congratulations on winning the yellow.  This is one of the images I "favorited," and I''m so looking forward to seeing your new drone photos.  A whole new world beckons!</td>', 'Congratulations on winning the yellow.  This is one of the images I "favorited," and I''m so looking forward to seeing your new drone photos.  A whole new world beckons!', '2020-07-13 17:39:23.000000', NULL, 0),
